import { useState, useMemo, useEffect } from 'preact/hooks';
import { render } from 'preact';
import { setupRerender, act } from 'preact/test-utils';
import { html } from '../../src';
import { createElement as h } from 'preact';
import { getScratch, setupScratch, teardown } from '../_util/helpers';

describe('scratch trace', () => {
	let scratch;

	beforeEach(() => {
		scratch = setupScratch();
	});

	afterEach(() => {
		teardown(scratch);
	});

	it('traces mount replay', () => {
		const calls = [];
		const App = () => {
			const [greeting, setGreeting] = useState('bye');
			calls.push('render ' + greeting);
			if (greeting === 'bye') {
				setGreeting('hi');
			}
			return h('p', null, greeting);
		};

		render(h(App), scratch);
		// eslint-disable-next-line no-console
		console.log('MOUNT CALLS: ' + JSON.stringify(calls));

		const calls2 = [];
		let set;
		const App2 = () => {
			const [greeting, setGreeting] = useState('hi');
			set = setGreeting;
			useEffect(() => {
				calls2.push('effect ' + greeting);
				return () => calls2.push('cleanup ' + greeting);
			}, [greeting]);
			calls2.push('render ' + greeting);
			if (greeting === 'bye') {
				setGreeting('hi');
			}
			return h('p', null, greeting);
		};

		render(h(App2), scratch);
		// eslint-disable-next-line no-console
		console.log('MOUNT2 CALLS (sync): ' + JSON.stringify(calls2));
	});
});

